/**
 * Mini Isisaurus (Tipo Agua) — Versión Chibi / Cría compañera de dinosaurio.
 * Basado en el arte oficial de Dinosaur King:
 *   assets/dinos/arte/agua/isisaurus_der.webp
 * Construido sobre la base anatómica de Mini Ampelosaurus (titanosaurio compañero).
 *
 * Características anatómicas del Isisaurus (Titanosaurio de la India):
 *   - Cuello corto, robusto y muy musculoso erguido a ~60°, cabezoncito alegre y expresivo.
 *   - Espalda inclinada con extremidades delanteras notablemente más altas y fuertes que las traseras.
 *   - Lomo, cuello, cola y costados protegidos por escudos dérmicos redondeados (osteodermos en cúpula/botón)
 *     de color crema marfil dorado (a diferencia de los cristales puntiagudos del Ampelosaurus).
 *   - Patitas columnares rechonchas cerradas en cúpula dentro del cuerpo (cero huecos).
 *   - Mandíbula inferior estilizada y articulada para rugir, con dientecitos de marfil.
 *   - Ojos grandes anime con iris verde esmeralda brillante y destellos de luz.
 *   - Proyección lateral de textura oficial con piel verde musgo / lima viva y vientre crema continuo.
 *   - Esqueleto con piel deformable (M.pielConHuesos) y animaciones completas (Reposo, Caminar, Rugir).
 */
registrarMalla({
  id: "mini_isisaurus",
  categoria: "mini dino",
  nombre: "Mini Isisaurus (Agua)",
  icono: "🦕",
  origen: "assets/dinos/arte/agua/isisaurus_der.webp",

  construir(M) {
    const g = new THREE.Group();
    const LADOS = [-1, 1];
    const L = (s) => (s > 0 ? "I" : "D");
    const V = (x, y, z) => new THREE.Vector3(x, y, z);
    const grad = Math.PI / 180;
    const cr = (p0, p1, p2, p3, t) => 0.5 * ((2 * p1) + (-p0 + p2) * t
      + (2 * p0 - 5 * p1 + 4 * p2 - p3) * t * t + (-p0 + 3 * p1 - 3 * p2 + p3) * t * t * t);

    const azar = M.azar(42);

    // ---------------- UTILIDADES GEOMÉTRICAS ----------------
    const suave = (a, b, x) => {
      const t = Math.max(0, Math.min(1, (x - a) / (b - a)));
      return t * t * (3 - 2 * t);
    };

    function rejilla(pos, cols, rows, nombre) {
      const idx = [];
      for (let r = 0; r < rows; r++) {
        for (let c = 0; c < cols; c++) {
          const a = r * (cols + 1) + c;
          const b = a + cols + 1;
          idx.push(a, b, a + 1, b, b + 1, a + 1);
        }
      }
      const geo = new THREE.BufferGeometry();
      geo.setAttribute("position", new THREE.Float32BufferAttribute(pos, 3));
      geo.setIndex(idx);
      geo.computeVertexNormals();
      return M.pieza(geo, nombre, cols, rows);
    }

    function bloque(x, y, z, rx, ry, rz, curva = 0.5, nombre = "Bloque", segA = 12, segB = 10) {
      const sW = M.seg(segA, 8);
      const sH = M.seg(segB, 6);
      const geo = new THREE.SphereGeometry(1, sW, sH);
      const pos = geo.attributes.position;
      for (let i = 0; i < pos.count; i++) {
        let px = pos.getX(i);
        let py = pos.getY(i);
        let pz = pos.getZ(i);
        if (curva < 0.999) {
          const fx = Math.pow(Math.abs(px), curva);
          const fy = Math.pow(Math.abs(py), curva);
          const fz = Math.pow(Math.abs(pz), curva);
          px = Math.sign(px) * fx;
          py = Math.sign(py) * fy;
          pz = Math.sign(pz) * fz;
        }
        pos.setXYZ(i, x + px * rx, y + py * ry, z + pz * rz);
      }
      geo.computeVertexNormals();
      return M.pieza(geo, nombre, sW, sH);
    }

    function punta(camino, radio, nombre, segL = 12, segR = 10) {
      const curva = M.curva(camino);
      const tSeg = M.seg(segL, 8);
      const rSeg = M.seg(segR, 6);
      const geo = new THREE.TubeGeometry(curva, tSeg, 1, rSeg, false);
      const pos = geo.attributes.position;
      const P = new THREE.Vector3();
      for (let i = 0; i <= tSeg; i++) {
        const t = i / tSeg;
        curva.getPointAt(t, P);
        const r = radio * Math.pow(Math.max(0, 1 - t), 0.65);
        for (let j = 0; j <= rSeg; j++) {
          const k = i * (rSeg + 1) + j;
          pos.setXYZ(k,
            P.x + (pos.getX(k) - P.x) * r,
            P.y + (pos.getY(k) - P.y) * r,
            P.z + (pos.getZ(k) - P.z) * r
          );
        }
      }
      return M.coserNormales(M.pieza(geo, nombre, rSeg, tSeg));
    }

    function almendra(rx, ry, rz, nombre = "Almendra", segA = 16, segB = 12) {
      const sW = M.seg(segA, 10);
      const sH = M.seg(segB, 8);
      const geo = new THREE.SphereGeometry(1, sW, sH);
      const pos = geo.attributes.position;
      for (let i = 0; i < pos.count; i++) {
        let x = pos.getX(i);
        let y = pos.getY(i);
        let z = pos.getZ(i);
        const f = 1 - 0.32 * Math.pow(Math.abs(x), 1.8);
        pos.setXYZ(i, x * rx, y * ry * f, z * rz);
      }
      geo.computeVertexNormals();
      return M.pieza(geo, nombre, sW, sH);
    }

    // Escudo dérmico / osteodermo redondeado en forma de botón / domo ovalado (propio del Isisaurus)
    function osteodermoDomo(base, dir, radio, alto, nombre = "OsteodermoDomo") {
      const sW = M.seg(10, 6);
      const sH = M.seg(8, 4);
      const geo = new THREE.SphereGeometry(1, sW, sH);
      const pos = geo.attributes.position;
      const up = new THREE.Vector3(0, 1, 0);
      const q = new THREE.Quaternion().setFromUnitVectors(up, dir.clone().normalize());

      for (let i = 0; i < pos.count; i++) {
        let x = pos.getX(i) * radio;
        let y = Math.max(0, pos.getY(i)) * alto; // semiesfera / domo con base plana
        let z = pos.getZ(i) * radio * 1.15;
        const v = new THREE.Vector3(x, y, z).applyQuaternion(q).add(base);
        pos.setXYZ(i, v.x, v.y, v.z);
      }
      geo.computeVertexNormals();
      return M.pieza(geo, nombre, sW, sH);
    }

    // ---------------- 1. CUERPO CONTINUO 100% CERRADO ----------------
    // Eje longitudinal con espalda inclinada típica de titanosaurio (hombros altos) y cuello musculoso:
    // [z, y, semiancho, altoHaciaArriba, altoHaciaAbajo, forma]
    const EJE = [
      [-0.74, 0.45, 0.000, 0.000, 0.000, 2.0],  // Punta cola cerrada
      [-0.70, 0.44, 0.038, 0.040, 0.038, 2.0],
      [-0.60, 0.42, 0.070, 0.075, 0.070, 2.1],  // Cola media
      [-0.46, 0.41, 0.115, 0.125, 0.115, 2.1],
      [-0.32, 0.42, 0.165, 0.175, 0.165, 2.2],  // Base de la cola
      [-0.16, 0.46, 0.220, 0.230, 0.230, 2.4],  // Cadera
      [ 0.00, 0.49, 0.250, 0.250, 0.260, 2.5],  // Vientre rechoncho
      [ 0.16, 0.53, 0.235, 0.255, 0.245, 2.4],  // Pecho y hombros prominentes
      [ 0.28, 0.60, 0.175, 0.190, 0.170, 2.3],  // Base del cuello ancha y musculosa
      [ 0.38, 0.72, 0.135, 0.150, 0.140, 2.2],  // Cuello robusto erguido
      [ 0.46, 0.84, 0.125, 0.135, 0.130, 2.2],  // Cuello superior
      [ 0.54, 0.92, 0.135, 0.145, 0.130, 2.3],  // Nuca
      [ 0.62, 0.93, 0.145, 0.155, 0.130, 2.4],  // Cráneo chibi
      [ 0.69, 0.90, 0.115, 0.125, 0.110, 2.3],  // Frente del hocico
      [ 0.73, 0.88, 0.075, 0.080, 0.070, 2.2],  // Hocico redondeado
      [ 0.75, 0.87, 0.000, 0.000, 0.000, 2.0]   // Cierre hermético
    ];

    const ejeCurva = new THREE.CatmullRomCurve3(EJE.map(([z, y]) => V(0, y, z)), false, "centripetal");
    ejeCurva.arcLengthDivisions = 1200;
    const LARGO = ejeCurva.getLength();

    function seccion(u) {
      const f = ejeCurva.getUtoTmapping(u) * (EJE.length - 1);
      const i = Math.min(EJE.length - 2, Math.floor(f));
      const t = f - i;
      const a = EJE[Math.max(0, i - 1)];
      const b = EJE[i];
      const c = EJE[i + 1];
      const d = EJE[Math.min(EJE.length - 1, i + 2)];
      return [2, 3, 4, 5].map((j) => Math.max(0, cr(a[j], b[j], c[j], d[j], t)));
    }

    const X = V(1, 0, 0);
    function marcoEje(u) {
      const P = ejeCurva.getPointAt(u);
      const T = ejeCurva.getTangentAt(u);
      const ang = Math.atan2(T.y, T.z);
      const angSuave = ang * 0.28;
      const U = V(0, Math.cos(angSuave), -Math.sin(angSuave));
      return { P, T, U };
    }

    function uCercano(p, desde = 0, hasta = 1) {
      let mejor = desde;
      let dMin = Infinity;
      for (let k = 0; k <= 400; k++) {
        const u = desde + (hasta - desde) * (k / 400);
        const d = ejeCurva.getPointAt(u).distanceToSquared(p);
        if (d < dMin) { dMin = d; mejor = u; }
      }
      return mejor;
    }

    function uEnZ(z) {
      let mejor = 0;
      let dMin = Infinity;
      for (let k = 0; k <= 300; k++) {
        const u = k / 300;
        const d = Math.abs(ejeCurva.getPointAt(u).z - z);
        if (d < dMin) { dMin = d; mejor = u; }
      }
      return mejor;
    }

    function enCuerpo(u, fi, despegue = 0) {
      const { P, U } = marcoEje(u);
      const [w, hA, hB, p] = seccion(u);
      const ex = 2 / p;
      const s = Math.sin(fi);
      const co = Math.cos(fi);
      const lx = (w + despegue) * Math.sign(s) * Math.pow(Math.abs(s), ex);
      const ly = ((co >= 0 ? hA : hB) + despegue) * Math.sign(co) * Math.pow(Math.abs(co), ex);
      return P.clone().addScaledVector(X, lx).addScaledVector(U, ly);
    }

    function haciaFuera(u, fi, atras = 0) {
      const { T, U } = marcoEje(u);
      const fuera = U.clone().multiplyScalar(Math.cos(fi)).addScaledVector(X, Math.sin(fi)).normalize();
      return fuera.multiplyScalar(Math.cos(atras * grad)).addScaledVector(T, -Math.sin(atras * grad)).normalize();
    }

    const COLS = M.seg(72, 20);
    const FILAS = M.seg(360, 60);
    const cuerpo = (() => {
      const pos = [];
      for (let r = 0; r <= FILAS; r++) {
        const u = r / FILAS;
        const { P, U } = marcoEje(u);
        const [w, hA, hB, p] = seccion(u);
        const ex = 2 / p;
        const z = P.z;

        const hombro = 0.048 * Math.exp(-Math.pow((z - 0.16) / 0.18, 2));
        const muslo = 0.046 * Math.exp(-Math.pow((z + 0.16) / 0.18, 2));

        for (let c = 0; c <= COLS; c++) {
          const fi = Math.PI + (c / COLS) * Math.PI * 2;
          const s = Math.sin(fi);
          const co = Math.cos(fi);
          const musculo = (hombro + muslo) * Math.pow(Math.abs(s), 1.6);
          const lx = (w + musculo) * Math.sign(s) * Math.pow(Math.abs(s), ex);
          const ly = ((co >= 0 ? hA : hB) + musculo * 0.4) * Math.sign(co) * Math.pow(Math.abs(co), ex);
          const pto = P.clone().addScaledVector(X, lx).addScaledVector(U, ly);
          pos.push(pto.x, pto.y, pto.z);
        }
      }
      return M.coserNormales(rejilla(pos, COLS, FILAS, "CuerpoIsisaurus"));
    })();

    // ---------------- 2. ESQUELETO Y RIGGING ----------------
    // Extremidades delanteras ligeramente más altas (titanosaurio):
    const MANO_X = 0.185;
    const PIE_X = 0.180;

    const HUESOS = [
      ["Raiz", null, 0, 0, 0],
      ["Cadera", "Raiz", 0, 0.48, -0.16],
      ["Cola1", "Cadera", 0, 0.44, -0.32],
      ["Cola2", "Cola1", 0, 0.43, -0.48],
      ["Cola3", "Cola2", 0, 0.45, -0.64],
      ["Pecho", "Cadera", 0, 0.52, 0.16],
      ["Cuello1", "Pecho", 0, 0.62, 0.28],
      ["Cuello2", "Cuello1", 0, 0.74, 0.40],
      ["Cabeza", "Cuello2", 0, 0.90, 0.54],
      ["Mandibula", "Cabeza", 0, 0.85, 0.55],
      ...LADOS.flatMap((s) => [
        // Patas delanteras más altas
        ["Brazo" + L(s), "Pecho", s * MANO_X, 0.50, 0.16],
        ["Antebrazo" + L(s), "Brazo" + L(s), s * MANO_X, 0.30, 0.16],
        ["Mano" + L(s), "Antebrazo" + L(s), s * MANO_X, 0.12, 0.16],
        // Patas traseras
        ["Muslo" + L(s), "Cadera", s * PIE_X, 0.46, -0.16],
        ["Pierna" + L(s), "Muslo" + L(s), s * PIE_X, 0.26, -0.16],
        ["Pata" + L(s), "Pierna" + L(s), s * PIE_X, 0.10, -0.16]
      ])
    ];

    const hueso = {};
    HUESOS.forEach(([nombre, padre, x, y, z]) => {
      const b = new THREE.Bone();
      b.name = "Hueso" + nombre;
      b.userData.reposo = V(x, y, z);
      const p = padre ? hueso[padre] : null;
      b.position.set(x, y, z).sub(p ? p.userData.reposo : V(0, 0, 0));
      (p || g).add(b);
      hueso[nombre] = b;
    });
    g.updateMatrixWorld(true);

    const colgar = (nombre, obj) => {
      const h = typeof nombre === "string" ? hueso[nombre] : nombre;
      if (!h || !obj) return obj;
      h.attach(obj);
      return obj;
    };

    const uH = (n, d1 = 0.2, d2 = 1) => uCercano(hueso[n].userData.reposo, d1, d2);
    const uCola3 = uCercano(hueso.Cola3.userData.reposo, 0, 0.35);
    const uCola2 = uCercano(hueso.Cola2.userData.reposo, 0.1, 0.45);

    const TRAMOS = [
      [0, "Cola3"],
      [uCola3, "Cola2"],
      [uCola2, "Cola1"],
      [uH("Cola1", 0.15, 0.5), "Cadera"],
      [uH("Pecho", 0.35, 0.65), "Pecho"],
      [uH("Cuello1", 0.45, 0.75), "Cuello1"],
      [uH("Cuello2", 0.60, 0.85), "Cuello2"],
      [uH("Cabeza", 0.70, 0.95), "Cabeza"]
    ];

    const MEZCLA = 0.20 / LARGO;
    function pesosTramos(u, tramos, mezcla) {
      let k = 0;
      while (k + 1 < tramos.length && u >= tramos[k + 1][0]) k++;
      const res = [[hueso[tramos[k][1]], 1]];
      if (k + 1 < tramos.length) {
        const w = suave(-mezcla, mezcla, u - tramos[k + 1][0]);
        if (w > 0) { res[0][1] = 1 - w; res.push([hueso[tramos[k + 1][1]], w]); }
      }
      if (k > 0) {
        const w = 1 - suave(-mezcla, mezcla, u - tramos[k][0]);
        if (w > 0) { res[0][1] *= 1 - w; res.push([hueso[tramos[k - 1][1]], w]); }
      }
      return res;
    }

    g.add(cuerpo);
    M.pielConHuesos(cuerpo, g, (i) => pesosTramos(Math.floor(i / (COLS + 1)) / FILAS, TRAMOS, MEZCLA));

    // ---------------- 3. PATAS RECHONCHAS CERRADAS (CERO PIEZAS ABIERTAS) ----------------
    function pataCerrada(s, camino, radios, huesosPata, nombre) {
      const curva = M.curva(camino);
      const tSeg = M.seg(20, 8);
      const rSeg = M.seg(24, 10);
      const geo = new THREE.TubeGeometry(curva, tSeg, 1, rSeg, false);
      const pos = geo.attributes.position;
      const P = new THREE.Vector3();

      for (let i = 0; i <= tSeg; i++) {
        const t = i / tSeg;
        curva.getPointAt(t, P);
        let r = M.interp(radios, t);
        if (t < 0.22) {
          r *= Math.sqrt(Math.max(0, 1 - Math.pow(1 - t / 0.22, 2)));
        }
        for (let j = 0; j <= rSeg; j++) {
          const k = i * (rSeg + 1) + j;
          pos.setXYZ(k,
            P.x + (pos.getX(k) - P.x) * r,
            P.y + (pos.getY(k) - P.y) * r,
            P.z + (pos.getZ(k) - P.z) * r
          );
        }
      }
      const malla = M.coserNormales(M.pieza(geo, nombre, rSeg, tSeg));
      g.add(malla);

      const tramos = [
        [0, huesosPata[0]],
        [0.45, huesosPata[1]],
        [0.80, huesosPata[2]]
      ];
      M.pielConHuesos(malla, g, (i) => pesosTramos(Math.floor(i / (rSeg + 1)) / tSeg, tramos, 0.22));
      return malla;
    }

    LADOS.forEach((s) => {
      // Delanteras (más largas y erguidas)
      const xM = s * MANO_X;
      pataCerrada(s,
        [[xM * 0.92, 0.52, 0.16], [xM, 0.44, 0.16], [xM, 0.28, 0.16], [xM, 0.14, 0.16], [xM, 0.05, 0.16]],
        [[0, 0.115], [0.25, 0.105], [0.55, 0.088], [0.80, 0.082], [1, 0.076]],
        ["Brazo" + L(s), "Antebrazo" + L(s), "Mano" + L(s)], "PataDelantera");

      colgar("Mano" + L(s), bloque(xM, 0.045, 0.16, 0.070, 0.038, 0.068, 0.8, "PieDelantero"));

      // Uñitas delanteras
      [-0.032, 0, 0.032].forEach((dx) => {
        const xg = xM + s * dx;
        colgar("Mano" + L(s), punta([
          [xg, 0.040, 0.20],
          [xg + s * dx * 0.12, 0.020, 0.235],
          [xg + s * dx * 0.20, 0.003, 0.255]
        ], 0.018, "GarraMano", 10, 8));
      });

      // Traseras
      const xP = s * PIE_X;
      pataCerrada(s,
        [[xP * 0.92, 0.48, -0.16], [xP, 0.40, -0.16], [xP, 0.25, -0.16], [xP, 0.12, -0.16], [xP, 0.05, -0.16]],
        [[0, 0.125], [0.25, 0.115], [0.55, 0.092], [0.80, 0.084], [1, 0.078]],
        ["Muslo" + L(s), "Pierna" + L(s), "Pata" + L(s)], "PataTrasera");

      colgar("Pata" + L(s), bloque(xP, 0.045, -0.16, 0.072, 0.038, 0.070, 0.8, "PieTrasero"));

      // Uñitas traseras
      [-0.034, 0, 0.034].forEach((dx) => {
        const xg = xP + s * dx;
        colgar("Pata" + L(s), punta([
          [xg, 0.040, -0.115],
          [xg + s * dx * 0.12, 0.020, -0.085],
          [xg + s * dx * 0.20, 0.003, -0.065]
        ], 0.018, "GarraPie", 10, 8));
      });
    });

    // ---------------- 4. ESCUDOS DÉRMICOS REDONDEADOS EN CÚPULA (OSTEODERMOS DE ISISAURUS) ----------------
    const duenoEn = (u) => {
      let dMin = Infinity, mejor = "Cadera";
      ["Cola3", "Cola2", "Cola1", "Cadera", "Pecho", "Cuello1", "Cuello2", "Cabeza"].forEach((nom) => {
        const d = Math.abs(u - uH(nom));
        if (d < dMin) { dMin = d; mejor = nom; }
      });
      return mejor;
    };

    // Fila dorsal central sobre el lomo y cuello
    const ALTO_LOMO = [
      [-0.24, 0.032, 0.040],
      [-0.16, 0.040, 0.048],
      [-0.08, 0.048, 0.054],
      [ 0.00, 0.052, 0.058],
      [ 0.08, 0.050, 0.055],
      [ 0.16, 0.044, 0.050],
      [ 0.24, 0.038, 0.045]
    ];

    ALTO_LOMO.forEach(([z, alto, rad]) => {
      const u = uEnZ(z);
      const hb = duenoEn(u);

      // Escudo central redondeado
      const baseCentral = enCuerpo(u, 0, -0.008);
      const dirCentral = haciaFuera(u, 0, -4);
      colgar(hb, osteodermoDomo(baseCentral, dirCentral, rad, alto, "OsteodermoDomoLomo"));

      // Filas laterales flanqueando en el lomo
      LADOS.forEach((s) => {
        [0.32, 0.58].forEach((fiBase, filaIdx) => {
          const fi = s * (fiBase + (azar() - 0.5) * 0.06);
          const aLado = alto * (filaIdx === 0 ? 0.85 : 0.68);
          const rLado = rad * (filaIdx === 0 ? 0.88 : 0.72);
          const baseLado = enCuerpo(u + (azar() - 0.5) * 0.01, fi, -0.006);
          const dirLado = haciaFuera(u, fi * 0.8, azar() * 8);
          colgar(hb, osteodermoDomo(baseLado, dirLado, rLado, aLado, "OsteodermoDomoFlanco"));
        });
      });
    });

    // Escudos en la parte superior del cuello
    const uCuello1 = uH("Cuello1");
    const uNuca = uH("Cabeza");
    for (let k = 0; k < 6; k++) {
      const u = uCuello1 + ((uNuca - uCuello1) * (k + 0.5)) / 6;
      const f = 1 - k / 6;
      const a = 0.024 + 0.016 * f;
      const r = 0.030 + 0.014 * f;
      const baseCuello = enCuerpo(u, 0, -0.006);
      const dirCuello = haciaFuera(u, 0, 15);
      colgar(duenoEn(u), osteodermoDomo(baseCuello, dirCuello, r, a, "OsteodermoDomoCuello"));
    }

    // Escudos a lo largo de la colita
    const uCola0 = uH("Cola1");
    for (let k = 0; k < 7; k++) {
      const u = uCola0 - ((uCola0 - uCola3) * (k + 0.5)) / 7;
      const f = 1 - k / 7;
      const a = 0.022 + 0.018 * f;
      const r = 0.026 + 0.016 * f;
      const baseCola = enCuerpo(u, 0, -0.006);
      const dirCola = haciaFuera(u, 0, 8);
      colgar(duenoEn(u), osteodermoDomo(baseCola, dirCola, r, a, "OsteodermoDomoCola"));
    }

    // ---------------- 5. CABEZA, MANDÍBULA Y DETALLES FACIALES ----------------
    const MAND_PERFIL = [
      [0.55, 0.875, 0.115, 0.028, 2.2],
      [0.61, 0.865, 0.112, 0.026, 2.2],
      [0.67, 0.852, 0.095, 0.024, 2.2],
      [0.72, 0.840, 0.060, 0.020, 2.1],
      [0.74, 0.835, 0.000, 0.000, 2.0]
    ];

    const colsMand = M.seg(48, 20);
    const filasMand = M.seg(32, 16);
    const posMand = [];

    for (let r = 0; r <= filasMand; r++) {
      const t = r / filasMand;
      const f = t * (MAND_PERFIL.length - 1);
      const i = Math.min(MAND_PERFIL.length - 2, Math.floor(f));
      const k = f - i;
      const a = MAND_PERFIL[Math.max(0, i - 1)];
      const b = MAND_PERFIL[i];
      const c = MAND_PERFIL[i + 1];
      const d = MAND_PERFIL[Math.min(MAND_PERFIL.length - 1, i + 2)];
      const [z, y, w, h, p] = [0, 1, 2, 3, 4].map((j) => cr(a[j], b[j], c[j], d[j], k));
      const ex = 2 / p;

      for (let col = 0; col <= colsMand; col++) {
        const fi = Math.PI + (col / colsMand) * Math.PI * 2;
        const s = Math.sin(fi);
        const co = Math.cos(fi);
        const lx = w * Math.sign(s) * Math.pow(Math.abs(s), ex);
        const ly = h * Math.sign(co) * Math.pow(Math.abs(co), ex);
        posMand.push(lx, y + ly, z);
      }
    }

    colgar("Mandibula", M.coserNormales(rejilla(posMand, colsMand, filasMand, "MandibulaIsis")));
    colgar("Mandibula", bloque(0, 0.865, 0.63, 0.052, 0.012, 0.075, 0.6, "Lengua"));

    LADOS.forEach((s) => {
      [0.60, 0.65, 0.70].forEach((z, idx) => {
        const wTeeth = 0.105 - idx * 0.018;
        const xTeeth = s * wTeeth;
        colgar("Mandibula", punta([[xTeeth, 0.865, z], [xTeeth, 0.880, z + 0.002]], 0.0055, "DienteInferior", 8, 6));
      });

      [0.61, 0.66, 0.71].forEach((z, idx) => {
        const wTeeth = 0.112 - idx * 0.018;
        const xTeeth = s * wTeeth;
        colgar("Cabeza", punta([[xTeeth, 0.886, z], [xTeeth, 0.870, z + 0.002]], 0.006, "DienteSuperior", 8, 6));
      });

      const labioPuntos = [
        [s * 0.120, 0.892, 0.58],
        [s * 0.110, 0.888, 0.63],
        [s * 0.095, 0.882, 0.68],
        [s * 0.065, 0.875, 0.72],
        [s * 0.008, 0.870, 0.74]
      ];
      colgar("Cabeza", M.tubo(labioPuntos, 0.006, 0.0045, { segLargo: 24, segRadio: 10, nombre: "LabioSuperior" }));
    });

    LADOS.forEach((s) => {
      colgar("Cabeza", bloque(s * 0.040, 0.935, 0.68, 0.008, 0.006, 0.010, 0.4, "FosaNasal", 10, 8));
    });

    LADOS.forEach((s) => {
      const ojoGrupo = new THREE.Group();
      ojoGrupo.position.set(s * 0.125, 0.940, 0.61);
      ojoGrupo.rotation.y = s * 0.35;

      ojoGrupo.add(almendra(0.045, 0.040, 0.014, "OjoBlanco"));
      ojoGrupo.add(bloque(s * 0.004, 0, 0.005, 0.032, 0.032, 0.008, 1, "IrisAgua"));
      ojoGrupo.add(bloque(s * 0.004, -0.002, 0.010, 0.018, 0.020, 0.006, 1, "Pupila"));
      ojoGrupo.add(bloque(-s * 0.010, 0.012, 0.014, 0.012, 0.012, 0.005, 1, "BrilloOjo"));
      ojoGrupo.add(bloque(s * 0.010, -0.010, 0.013, 0.006, 0.006, 0.004, 1, "BrilloOjoPequeno"));

      ojoGrupo.add(M.tubo([
        [-0.040, 0.005, 0.006],
        [0, 0.038, 0.011],
        [0.040, 0.005, 0.006]
      ], 0.005, 0.004, { segLargo: 10, segRadio: 8, nombre: "ParpadoSuperior" }));

      ojoGrupo.add(M.tubo([
        [-0.036, -0.005, 0.006],
        [0, -0.035, 0.009],
        [0.036, -0.005, 0.006]
      ], 0.0045, 0.0035, { segLargo: 10, segRadio: 8, nombre: "ParpadoInferior" }));

      colgar("Cabeza", ojoGrupo);
    });

    // ---------------- 6. PINTURA: PROYECCIÓN Y COLORES DE ISISAURUS_DER.WEBP ----------------
    const TEXTURA = this.textura;
    const proyectar = M.proyeccion(TEXTURA, 1.05);

    const C_VERDE_BASE = new THREE.Color(0x649e4e);
    const C_CREMA_VIENTRE = new THREE.Color(0xf2eecb);
    const C_OSTEODERMO = new THREE.Color(0xe6dcbc);
    const C_LENGUA = new THREE.Color(0xd97575);
    const MARFIL = new THREE.Color(0xfbf6ea);
    const cColor = new THREE.Color();

    M.pintar(cuerpo, (i, p) => {
      proyectar(p.z, p.y, cColor);

      if (cColor.r < 0.10 && cColor.g < 0.10 && cColor.b < 0.10) {
        cColor.copy(C_VERDE_BASE);
      }

      // Vientre y garganta más claros continuos en la parte inferior
      const u = Math.floor(i / (COLS + 1)) / FILAS;
      const cIdx = i % (COLS + 1);
      const fi = Math.PI + (cIdx / COLS) * Math.PI * 2;
      const co = Math.cos(fi);

      if (co < 0 && p.y < 0.72 && u > 0.14 && u < 0.92) {
        const factorVientre = Math.pow(-co, 1.4) * suave(0.72, 0.40, p.y);
        cColor.lerp(C_CREMA_VIENTRE, Math.min(1, factorVientre * 0.90));
      }

      return cColor;
    }, g);

    const COLOR_PIEZAS = {
      pataDelantera: 0x6e9f58,
      pataTrasera: 0x5a8a47,
      mandibula: 0x689b53,
      labio: 0x487537,
      fosaNasal: 0x2e4f21,
      parpado: 0x548242,
      iris: 0x10b981,
      pupila: 0x062817,
      brillo: 0xffffff,
      ojoBlanco: 0xfefcf9
    };

    const piezas = [];
    g.traverse((o) => { if (o.isMesh && o !== cuerpo) piezas.push(o); });

    piezas.forEach((o) => {
      if (/^(Diente|Garra)/.test(o.name)) return M.pintar(o, () => MARFIL, g);
      if (/^Osteodermo/.test(o.name)) return M.pintar(o, () => C_OSTEODERMO, g);
      if (o.name === "Lengua") return M.pintar(o, () => C_LENGUA, g);
      if (o.name === "OjoBlanco") return M.pintar(o, () => new THREE.Color(COLOR_PIEZAS.ojoBlanco), g);
      if (o.name === "IrisAgua") return M.pintar(o, () => new THREE.Color(COLOR_PIEZAS.iris), g);
      if (o.name === "Pupila") return M.pintar(o, () => new THREE.Color(COLOR_PIEZAS.pupila), g);
      if (/^BrilloOjo/.test(o.name)) return M.pintar(o, () => new THREE.Color(COLOR_PIEZAS.brillo), g);
      if (/^Parpado/.test(o.name)) return M.pintar(o, () => new THREE.Color(COLOR_PIEZAS.parpado), g);
      if (o.name === "LabioSuperior") return M.pintar(o, () => new THREE.Color(COLOR_PIEZAS.labio), g);
      if (o.name === "FosaNasal") return M.pintar(o, () => new THREE.Color(COLOR_PIEZAS.fosaNasal), g);

      if (o.name === "MandibulaIsis") {
        return M.pintar(o, (i, p) => {
          proyectar(p.z, p.y, cColor);
          if (cColor.r < 0.10 && cColor.g < 0.10 && cColor.b < 0.10) cColor.setHex(COLOR_PIEZAS.mandibula);
          return cColor;
        }, g);
      }

      if (o.name === "PataDelantera" || o.name === "PieDelantero") {
        return M.pintar(o, (i, p) => {
          proyectar(p.z, Math.max(p.y, 0.18), cColor);
          if (cColor.r < 0.10 && cColor.g < 0.10 && cColor.b < 0.10) cColor.setHex(COLOR_PIEZAS.pataDelantera);
          return cColor;
        }, g);
      }

      if (o.name === "PataTrasera" || o.name === "PieTrasero") {
        return M.pintar(o, (i, p) => {
          proyectar(p.z, Math.max(p.y, 0.18), cColor);
          if (cColor.r < 0.10 && cColor.g < 0.10 && cColor.b < 0.10) cColor.setHex(COLOR_PIEZAS.pataTrasera);
          return cColor;
        }, g);
      }

      M.pintar(o, (i, p) => {
        proyectar(p.z, p.y, cColor);
        if (cColor.r < 0.10 && cColor.g < 0.10 && cColor.b < 0.10) cColor.copy(C_VERDE_BASE);
        return cColor;
      }, g);
    });

    // ---------------- 7. ANIMACIONES CHIBI (THREE.AnimationMixer) ----------------
    const q = new THREE.Quaternion();
    const eu = new THREE.Euler();
    function giro(nombre, dur, fn, n = 32) {
      const tiempos = [];
      const valores = [];
      for (let i = 0; i <= n; i++) {
        const [x, y, z] = fn(i / n);
        eu.set(x * grad, y * grad, z * grad);
        q.setFromEuler(eu);
        tiempos.push(i * (dur / n));
        valores.push(q.x, q.y, q.z, q.w);
      }
      return new THREE.QuaternionKeyframeTrack("Hueso" + nombre + ".quaternion", tiempos, valores);
    }

    function sube(nombre, dur, fn, n = 32) {
      const tiempos = [];
      const valores = [];
      const [x0, y0, z0] = hueso[nombre].position.toArray();
      for (let i = 0; i <= n; i++) {
        tiempos.push(i * (dur / n));
        valores.push(x0, y0 + fn(i / n), z0);
      }
      return new THREE.VectorKeyframeTrack("Hueso" + nombre + ".position", tiempos, valores);
    }

    const sen = (t, c = 1) => Math.sin(t * Math.PI * 2 * c);
    const cos = (t, c = 1) => Math.cos(t * Math.PI * 2 * c);

    const dR = 3.6;
    const reposo = new THREE.AnimationClip("Reposo", dR, [
      sube("Cadera", dR, (t) => 0.008 * sen(t)),
      giro("Pecho", dR, (t) => [1.2 * sen(t), 0, 0]),
      giro("Cuello1", dR, (t) => [-1.8 * sen(t), 0, 0]),
      giro("Cuello2", dR, (t) => [2.2 * sen(t), 1.5 * cos(t), 0]),
      giro("Cabeza", dR, (t) => [-1.5 * sen(t), 2.0 * cos(t), 1.0 * sen(t)]),
      giro("Cola1", dR, (t) => [1.0 * sen(t), 3.0 * sen(t), 0]),
      giro("Cola2", dR, (t) => [1.5 * sen(t), 5.0 * sen(t), 0]),
      giro("Cola3", dR, (t) => [2.0 * sen(t), 7.0 * sen(t), 0]),
      ...LADOS.flatMap((s) => [
        giro("Brazo" + L(s), dR, (t) => [-1.0 * sen(t), 0, 0]),
        giro("Muslo" + L(s), dR, (t) => [1.0 * sen(t), 0, 0])
      ])
    ]);

    const dC = 2.4;
    const PASO = 18;
    const caminar = new THREE.AnimationClip("Caminar", dC, [
      sube("Cadera", dC, (t) => 0.015 * sen(t, 2)),
      giro("Cadera", dC, (t) => [1.5 * sen(t, 2), 3 * sen(t), 0]),
      giro("Pecho", dC, (t) => [-1.5 * sen(t, 2), -3 * sen(t), 0]),
      giro("Cuello1", dC, (t) => [2.5 * sen(t, 2), 2 * sen(t), 0]),
      giro("Cuello2", dC, (t) => [-2.0 * sen(t, 2), 3 * sen(t), 0]),
      giro("Cabeza", dC, (t) => [2.0 * sen(t, 2), 2 * sen(t), 0]),
      giro("Cola1", dC, (t) => [1.0 * sen(t, 2), -5 * sen(t), 0]),
      giro("Cola2", dC, (t) => [1.5 * sen(t, 2), -9 * sen(t), 0]),
      giro("Cola3", dC, (t) => [2.0 * sen(t, 2), -14 * sen(t), 0]),
      ...LADOS.flatMap((s) => [
        giro("Brazo" + L(s), dC, (t) => [s * PASO * sen(t), 0, 0]),
        giro("Antebrazo" + L(s), dC, (t) => [s * Math.max(0, -PASO * 0.7 * sen(t)), 0, 0]),
        giro("Muslo" + L(s), dC, (t) => [s * -PASO * sen(t), 0, 0]),
        giro("Pierna" + L(s), dC, (t) => [s * Math.max(0, PASO * 0.7 * sen(t)), 0, 0])
      ])
    ]);

    const dG = 2.0;
    const alzar = [[0, 0], [0.25, 1], [0.75, 1], [1, 0]];
    const abrirBoca = [[0, 0], [0.25, 0], [0.42, 1], [0.72, 1], [0.88, 0], [1, 0]];
    const rugir = new THREE.AnimationClip("Rugir", dG, [
      sube("Cadera", dG, (t) => 0.040 * M.interp(alzar, t)),
      giro("Cadera", dG, (t) => [-12 * M.interp(alzar, t), 0, 0]),
      giro("Pecho", dG, (t) => [-16 * M.interp(alzar, t), 0, 0]),
      giro("Cuello1", dG, (t) => [14 * M.interp(alzar, t), 0, 0]),
      giro("Cuello2", dG, (t) => [18 * M.interp(alzar, t), 0, 0]),
      giro("Cabeza", dG, (t) => [12 * M.interp(alzar, t), 0, 0]),
      giro("Mandibula", dG, (t) => [26 * M.interp(abrirBoca, t), 0, 0]),
      giro("Cola1", dG, (t) => [4 * M.interp(alzar, t), 8 * sen(t, 2), 0]),
      giro("Cola2", dG, (t) => [6 * M.interp(alzar, t), 16 * sen(t, 2), 0]),
      giro("Cola3", dG, (t) => [8 * M.interp(alzar, t), 24 * sen(t, 2), 0]),
      ...LADOS.flatMap((s) => [
        giro("Brazo" + L(s), dG, (t) => [-22 * M.interp(alzar, t), 0, s * 6]),
        giro("Muslo" + L(s), dG, (t) => [10 * M.interp(alzar, t), 0, 0])
      ])
    ]);

    g.animations = [reposo, caminar, rugir];
    hueso.Raiz.userData.esqueleto = HUESOS.map(([nombre]) => "Hueso" + nombre);

    return g;
  },

  textura: {
    w: 260, h: 165, k: 2, esc: 0.00285, x0: 260, y0: 330,
    datos: ""
  }
});
